from pathlib import Path
from html import escape
import json
R=Path(__file__).parent
nav='<a href="/">Home</a><a href="/project/">Projects</a><a href="/services/">Services</a><a href="/acg-partnerships/">ACG Partnerships</a><a href="/talents/">Talents</a><a href="/news/">News</a><a href="/media/">Media</a><a href="/about/">About</a><a href="/contact/">Contact</a>'
languages='<div class="lang"><a href="/" lang="en">EN</a><a href="/zh-hant/" lang="zh-Hant">繁</a><a href="/zh-hans/" lang="zh-Hans">简</a><a href="/ja/" lang="ja">日</a><a href="/ko/" lang="ko">한</a></div>'
def game_schema(name, url, description, genre, status, image=None, same_as=None):
 data={'@type':'VideoGame','@id':url+'#game','name':name,'url':url,'description':description,'genre':genre,
       'creator':{'@id':'https://www.aurora-studio.org/#organization'},'publisher':{'@id':'https://www.aurora-studio.org/#organization'},
       'gamePlatform':'PC','applicationCategory':'Game','creativeWorkStatus':status}
 if image: data['image']='https://www.aurora-studio.org'+image
 if same_as: data['sameAs']=same_as
 return data

def news_schema(title, url, description, date, image=None):
 data={'@type':'NewsArticle','@id':url+'#article','headline':title,'url':url,'description':description,
       'datePublished':date,'dateModified':date,'author':{'@id':'https://www.aurora-studio.org/#organization'},
       'publisher':{'@id':'https://www.aurora-studio.org/#organization'},'mainEntityOfPage':{'@id':url+'#webpage'}}
 if image: data['image']='https://www.aurora-studio.org'+image
 return data

def acg_service_schema(url, title, description):
 return {'@type':'Service','@id':url+'#service','name':title,
         'description':description,'serviceType':'ACG partnership strategy and local activation planning',
         'provider':{'@id':'https://www.aurora-studio.org/#organization'},
         'areaServed':[{'@type':'Place','name':name} for name in ('Hong Kong','Greater Bay Area','Japan')]}

def page(title,description,content,filename, schema=None, lang='en'):
 alternates = '<link rel="alternate" hreflang="en" href="https://www.aurora-studio.org/"><link rel="alternate" hreflang="zh-Hant" href="https://www.aurora-studio.org/zh-hant/"><link rel="alternate" hreflang="zh-Hans" href="https://www.aurora-studio.org/zh-hans/"><link rel="alternate" hreflang="ja" href="https://www.aurora-studio.org/ja/"><link rel="alternate" hreflang="ko" href="https://www.aurora-studio.org/ko/"><link rel="alternate" hreflang="x-default" href="https://www.aurora-studio.org/">' if filename == 'index.html' else ''
 path = filename.replace('index.html','')
 canonical = f'https://www.aurora-studio.org/{path}'
 acg_routes = {'en':'/acg-partnerships/','zh-Hant':'/zh-hant/acg-partnerships/','zh-Hans':'/zh-hans/acg-partnerships/','ja':'/ja/acg-partnerships/'}
 is_acg = path.endswith('acg-partnerships/')
 if is_acg:
  alternates = ''.join(f'<link rel="alternate" hreflang="{code}" href="https://www.aurora-studio.org{route}">' for code,route in acg_routes.items()) + '<link rel="alternate" hreflang="x-default" href="https://www.aurora-studio.org/acg-partnerships/">'
 base_schema = {
  '@context':'https://schema.org',
  '@graph':[
   {
    '@type':'Organization','@id':'https://www.aurora-studio.org/#organization',
    'name':'Aurora Studio','url':'https://www.aurora-studio.org/',
    'description':'Independent game development studio based in Hong Kong, creating simulation and narrative experiences inspired by East Asia.',
    'founder':{'@type':'Person','@id':'https://www.aurora-studio.org/#shiko-leung','name':'Shiko Leung'},
    'areaServed':'Worldwide'
   },
   {
    '@type':'WebSite','@id':'https://www.aurora-studio.org/#website',
    'url':'https://www.aurora-studio.org/','name':'Aurora Studio',
    'publisher':{'@id':'https://www.aurora-studio.org/#organization'}
   },
   {
    '@type':'WebPage','@id':canonical+'#webpage','url':canonical,'name':title,
    'description':description,'isPartOf':{'@id':'https://www.aurora-studio.org/#website'},
    'about':{'@id':'https://www.aurora-studio.org/#organization'}
   }
  ]
 }
 if schema:
  base_schema['@graph'].append(schema)
 if is_acg:
  base_schema['@graph'].append(acg_service_schema(canonical,title,description))
  base_schema['@graph'][2]['inLanguage']=lang
 schema_json = json.dumps(base_schema, ensure_ascii=False, separators=(',',':')).replace('</','<\\/')
 is_acg_news = filename == 'news/acg-partnerships-launch/index.html'
 social = ''
 if is_acg or is_acg_news:
  social_image = 'https://www.aurora-studio.org/assets/numazu-route.jpg'
  social_type = 'article' if is_acg_news else 'website'
  social = (f'<meta property="og:type" content="{social_type}"><meta property="og:site_name" content="Aurora Studio">'
            f'<meta property="og:title" content="{escape(title, quote=True)}">'
            f'<meta property="og:description" content="{escape(description, quote=True)}">'
            f'<meta property="og:url" content="{canonical}"><meta property="og:image" content="{social_image}">'
            f'<meta property="og:image:alt" content="Project Numazu streetscape by Aurora Studio">'
            f'<meta name="twitter:card" content="summary_large_image">')
  if is_acg:
   social += f'<meta property="og:locale" content="{ {"en":"en_US","zh-Hant":"zh_HK","zh-Hans":"zh_CN","ja":"ja_JP"}[lang] }">'
  else:
   social += '<meta property="article:published_time" content="2026-09-28">'
 html=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>{escape(title)} | Aurora Studio</title><meta name="description" content="{escape(description)}"><link rel="canonical" href="{canonical}">{alternates}<link rel="icon" href="/assets/aurora-studio-icon.png?v=20260925" type="image/png"><link rel="apple-touch-icon" href="/assets/aurora-studio-icon.png"><link rel="stylesheet" href="/style.css?v=20260926e"><script type="application/ld+json">{schema_json}</script></head><body><a class="skip" href="#main">Skip to content</a><header class="site-header"><a href="/" class="brand" aria-label="Aurora Studio home"><span class="brand-mark" aria-hidden="true"><img src="/assets/aurora-studio-logo.jpeg" alt="" width="1500" height="1000"></span><span class="brand-name">Aurora Studio</span></a><nav aria-label="Main navigation">{nav}</nav>{languages}<a class="header-contact" href="mailto:press@aurora-studio.org">Get in touch <span aria-hidden="true">↗</span></a></header><main id="main">{content}</main><footer><div><strong>AURORA STUDIO</strong><p>Independent game development · Hong Kong</p></div><div><a href="/project/">Projects</a><a href="/services/">Services</a><a href="/acg-partnerships/">ACG Partnerships</a><a href="/talents/">Talents</a><a href="/news/">News</a><a href="/media/">Media</a><a href="/support/">Support</a><a href="/governance/">Governance</a><a href="/contact/">Contact</a></div><small>© 2026 Aurora Studio</small></footer></body></html>'''
 if is_acg:
  language_menu = '<div class="lang" aria-label="Page language">' + ''.join(f'<a href="{acg_routes[code]}" lang="{code}"' + (' aria-current="page"' if code == lang else '') + f'>{label}</a>' for code,label in [('en','EN'),('zh-Hant','繁'),('zh-Hans','简'),('ja','日')]) + '</div>'
  html = html.replace(languages, language_menu).replace('<html lang="en">',f'<html lang="{lang}">')
  ui = {
   'zh-Hant':('首頁 (EN)','作品 (EN)','服務 (EN)','ACG 跨境合作','虛擬藝人 (EN)','最新消息 (EN)','媒體 (EN)','關於 (EN)','聯絡 (EN)','開始洽談','跳至內容','香港獨立遊戲開發'),
   'zh-Hans':('首页 (EN)','作品 (EN)','服务 (EN)','ACG 跨境合作','虚拟艺人 (EN)','最新消息 (EN)','媒体 (EN)','关于 (EN)','联系 (EN)','洽谈合作','跳转至正文','香港独立游戏开发'),
   'ja':('ホーム (EN)','作品 (EN)','サービス (EN)','ACG事業提携','バーチャルタレント (EN)','ニュース (EN)','メディア (EN)','スタジオ紹介 (EN)','お問い合わせ (EN)','お問い合わせ','本文へ移動','香港のインディーゲーム開発')
  }
  if lang in ui:
   home,projects,services,acg,talents,news,media,about,contact,cta,skip,footnote=ui[lang]
   nav_local=''.join(f'<a href="{href}">{label}</a>' for href,label in [('/',home),('/project/',projects),('/services/',services),('/'+path,acg),('/talents/',talents),('/news/',news),('/media/',media),('/about/',about),('/contact/',contact)])
   footer_local=''.join(f'<a href="{href}">{label}</a>' for href,label in [('/project/',projects),('/services/',services),('/'+path,acg),('/talents/',talents),('/news/',news),('/media/',media),('/support/','Support (EN)'),('/governance/','Governance (EN)'),('/contact/',contact)])
   html=html.replace(f'<nav aria-label="Main navigation">{nav}</nav>',f'<nav aria-label="Main navigation">{nav_local}</nav>')
   html=html.replace('<a class="header-contact" href="mailto:press@aurora-studio.org">Get in touch',f'<a class="header-contact" href="mailto:press@aurora-studio.org">{cta}')
   html=html.replace('<a class="skip" href="#main">Skip to content',f'<a class="skip" href="#main">{skip}')
   html=html.replace('<p>Independent game development · Hong Kong</p>',f'<p>{footnote}</p>')
   html=html.replace('<div><a href="/project/">Projects</a><a href="/services/">Services</a><a href="/acg-partnerships/">ACG Partnerships</a><a href="/talents/">Talents</a><a href="/news/">News</a><a href="/media/">Media</a><a href="/support/">Support</a><a href="/governance/">Governance</a><a href="/contact/">Contact</a></div>',f'<div>{footer_local}</div>')
 if social:
  html=html.replace('</head>',social+'</head>',1)
 if is_acg:
  html=html.replace('/style.css?v=20260926e','/style.css?v=20260928f',1)
 p=R/filename;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(html)
page('Independent games from Hong Kong','Aurora Studio creates simulation and narrative experiences inspired by Asia.','''<section class="hero"><img class="hero-image" src="/assets/numazu-buses.jpg" alt="Two buses in the Project Numazu game environment" fetchpriority="high"><div class="hero-shade"></div><div class="hero-content"><p class="eyebrow">INDEPENDENT GAME STUDIO · HONG KONG</p><h1>Places worth<br><em>getting lost in.</em></h1><p>We build simulation and narrative worlds shaped by the details, stories and streets of East Asia.</p><div class="actions"><a class="button light" href="/project/">Explore our projects <span aria-hidden="true">↗</span></a><a class="text-link" href="/about/">Meet the studio <span aria-hidden="true">→</span></a></div></div><div class="hero-caption">01 / OMSI 2 ADD-ON: PROJECT NUMAZU</div></section><section class="section intro"><div><p class="eyebrow dark">WHAT WE MAKE</p><h2>Built with a sense<br>of place.</h2></div><p>From a bus journey through Shizuoka to a supernatural pilgrimage across Edo-period Japan, we make worlds that reward curiosity and attention.</p></section><section class="section projects"><div class="section-head"><p class="eyebrow dark">SELECTED WORK</p><a href="/project/">All projects ↗</a></div><div class="project-grid"><a class="feature-card" href="/project/project-numazu/"><img src="/assets/numazu-route.jpg" alt="Bus travelling through a Project Numazu street" loading="lazy"><div><span>SIMULATION · RELEASED</span><h3>Project Numazu</h3><p>A carefully reconstructed Japanese city for OMSI 2.</p><b aria-hidden="true">↗</b></div></a><a class="type-card" href="/project/revenant-of-tsushima/"><img class="rot-card-image" src="/assets/revenant-cover-clean.jpg" alt="Revenant of Tsushima poster with Tsushima Mewa and supernatural figures under a moonlit sky" loading="lazy"><span>NARRATIVE HORROR · IN DEVELOPMENT</span><h3>Revenant of Tsushima</h3><p>An Edo-era folk horror journey through memory, ritual and the supernatural.</p><b aria-hidden="true">↗</b></a></div></section><section class="section home-extras"><div class="info-panel"><p class="eyebrow dark">COLLABORATE</p><h2>Build with us.</h2><p>Environment production, simulation design and game prototypes informed by years of work on place-based worlds.</p><a href="/services/">Explore services ↗</a><a href="/acg-partnerships/">Explore ACG partnerships ↗</a></div><div class="info-panel"><p class="eyebrow dark">SUPPORT THE STUDIO</p><h2>Help keep our worlds growing.</h2><p>Follow development and support independent production through the Aurora Studio Supporters Club.</p><a href="/support/">Ways to support ↗</a></div></section><section class="section home-talent"><div><p class="eyebrow dark">MEET OUR VIRTUAL TALENT</p><h2>Stories have a host.</h2><p>Tsushima Mewa takes Aurora Studio’s original character beyond the game, exploring Hong Kong urban folklore on Mewa Ch.</p><a href="/talents/">Meet Mewa ↗</a></div><a href="/talents/" class="home-talent-art"><img src="/assets/revenant-cover-clean.jpg" alt="Artwork featuring Tsushima Mewa" loading="lazy"></a></section><section class="section home-media"><div><p class="eyebrow dark">WATCH THE WORK</p><h2>Stories in motion.</h2><p>Watch our game trailers, read independent coverage and revisit creators exploring Numazu.</p><a href="/media/">Visit the media room ↗</a></div><a class="home-media-art" href="/media/"><img src="/assets/numazu-route.jpg" alt="Project Numazu street scene" loading="lazy"><span>TRAILERS · PRESS · PLAY SESSIONS ↗</span></a></section><section class="callout"><p class="eyebrow">LET'S CONNECT</p><h2>Have a story to tell<br>or a world to build?</h2><a class="button light" href="/contact/">Contact the studio ↗</a></section>''','index.html')
page("ACG Partnership Strategy in Hong Kong, Greater Bay Area & Japan","Plan ACG brand and venue collaborations across Hong Kong, the Greater Bay Area and Japan. Aurora Studio supports partner outreach, localization and local activations.",'''<section class="page-heading agency-heading"><p class="eyebrow dark">AURORA STUDIO / CROSS-BORDER COLLABORATION</p><h1>ACG partnerships<br><em>across borders.</em></h1><p>ACG partnership strategy and local production for brands, venues and entertainment teams connecting Hong Kong and the Greater Bay Area with Japan and global creative industries.</p><div class="actions"><a class="button dark" href="mailto:press@aurora-studio.org?subject=ACG%20partnership%20enquiry">Start a conversation ↗</a><a class="text-link" href="#approach">How we work ↓</a></div></section><section class="section agency-intro" id="approach"><div><p class="eyebrow dark">THE OPPORTUNITY</p><h2>Make the right idea<br>work in the right market.</h2></div><div><p>A strong IP collaboration needs more than an introduction. It needs a clear commercial brief, a realistic rights and approvals path, a local production plan and a campaign that gives audiences a reason to show up.</p><p>Aurora Studio combines game development and cross-border entertainment campaign experience to help turn that brief into a proposal that both local clients and prospective rights holders can evaluate.</p></div></section><section class="section agency-services"><div class="section-head"><p class="eyebrow dark">WHAT WE CAN SUPPORT</p><span>FROM BRIEF TO ACTIVATION</span></div><div class="agency-grid"><article><span>01 / STRATEGY</span><h3>Partnership concept</h3><p>Audience fit, IP shortlist, campaign format, objectives and a practical scope for review.</p></article><article><span>02 / BUSINESS DEVELOPMENT</span><h3>Rights-holder outreach</h3><p>Proposal preparation, introductions where appropriate and communication support through licensing discussions.</p></article><article><span>03 / EXPERIENCE</span><h3>Local activation</h3><p>Pop-ups, exhibitions, retail and F&amp;B concepts, fan experiences and interactive campaigns with suitable production partners.</p></article><article><span>04 / AMPLIFICATION</span><h3>Creators &amp; media</h3><p>Creator briefs, press materials, localization, deliverables and campaign coordination across markets.</p></article></div></section><section class="agency-band"><div class="section"><p class="eyebrow">HONG KONG · GREATER BAY AREA · JAPAN · GLOBAL</p><h2>One brief. Multiple creative worlds.</h2><p>For malls and destinations, consumer brands, tourism and cultural teams, game publishers and entertainment IP owners exploring cross-border audiences.</p></div></section><section class="section agency-proof"><div><p class="eyebrow dark">SELECTED EXPERIENCE</p><h2>Built through real projects.</h2><p>Our game work has involved international publishing, Japanese creator promotion and media outreach in Japan and Taiwan. Project Numazu offers a public example of how a place-based game can connect development, creators and regional audiences.</p><a href="/media/#numazu">View public campaign and media examples ↗</a></div><div class="agency-proof-card"><span>PROJECT NUMAZU / 2026</span><h3>A city, a game, a cross-border campaign.</h3><p>Released for OMSI 2 with an international publisher; supported by creator activity and coverage in Japanese and Taiwanese game media.</p><a href="/project/project-numazu/">Explore the project ↗</a></div></section><section class="section agency-process"><p class="eyebrow dark">HOW AN ENGAGEMENT BEGINS</p><div><span>01</span><h3>Tell us the objective.</h3><p>Share your audience, location, timing, budget range and desired outcome.</p></div><div><span>02</span><h3>Shape a viable concept.</h3><p>We identify formats, possible partners, approval needs and delivery scope.</p></div><div><span>03</span><h3>Agree the next step.</h3><p>We set a defined discovery or production brief before approaching rights holders or vendors.</p></div></section><section class="section agency-faq" id="faq"><p class="eyebrow dark">FAQ</p><h2>Frequently asked questions.</h2><div class="agency-faq-list"><details><summary>Does Aurora Studio represent any specific IP or guarantee access?</summary><p>No. Aurora Studio does not represent third-party IP or guarantee licensing or talent access. Every collaboration depends on the rights holder’s interest, approvals, availability and agreed commercial terms.</p></details><details><summary>Who can work with Aurora Studio?</summary><p>We welcome enquiries from malls and venues, consumer brands, tourism and cultural teams, game publishers and entertainment companies with a defined audience and campaign objective.</p></details><details><summary>What does the service include?</summary><p>Depending on the brief, we can support audience and IP fit, partnership proposals, appropriate rights-holder outreach, local activation planning, localization, and creator and media coordination.</p></details><details><summary>When would you contact a rights holder?</summary><p>We first agree the objective, budget range, scope and deliverables with the client. Any outreach to a rights holder or production partner follows a defined brief.</p></details><details><summary>What should we include in an initial enquiry?</summary><p>Tell us the target audience, proposed location, campaign window, indicative budget and desired outcome. You may also share a preferred IP or initial concept.</p></details></div></section><section class="callout"><p class="eyebrow">LET'S BUILD THE BRIEF</p><h2>Have a market in mind?<br>Let's find the right story.</h2><p>Send the location, campaign window, budget range and the kind of audience you want to reach.</p><a class="button light" href="mailto:press@aurora-studio.org?subject=ACG%20partnership%20enquiry">Email Aurora Studio ↗</a><p class="agency-note">All IP, talent and brand collaborations depend on the relevant rights holders’ interest, approvals, availability and agreed commercial terms. Aurora Studio does not represent or guarantee access to any third-party IP.</p></section>''','acg-partnerships/index.html')
page('Projects','Explore Project Numazu, Revenant of Tsushima, Railway Depot and Aurora Engine.','''<section class="page-heading"><p class="eyebrow dark">OUR WORK</p><h1>Projects<span class="dot">.</span></h1><p>Simulated places, lived-in systems and stories from East Asia.</p></section><section class="section project-list"><article class="listing"><img src="/assets/numazu-buses.jpg" alt="Two buses in Project Numazu"><div><span class="eyebrow dark">01 / SIMULATION · RELEASED</span><h2>OMSI 2: Project Numazu</h2><p>Drive through a 1:1 scale recreation of Numazu, Shizuoka, from its station district to the coastal landmarks and everyday streets around it.</p><a href="/project/project-numazu/">Explore Project Numazu ↗</a></div></article><article class="listing alt"><img class="rot-list-art" src="/assets/revenant-cover-clean.jpg" alt="Revenant of Tsushima poster" loading="lazy"><div><span class="eyebrow dark">02 / FOLK HORROR · IN DEVELOPMENT</span><h2>Revenant of Tsushima</h2><p>A first-person journey through an Edo-period Japan reshaped by the awakening of Tsushima Mewa, a shrine maiden sealed for more than three centuries.</p><a href="/project/revenant-of-tsushima/">Visit official project site ↗</a></div></article><article class="mini-list"><span>03 / MANAGEMENT SIMULATION</span><h2>Railway Depot: Operations &amp; Empire</h2><p>Run the railway behind the trains: depot operations, maintenance and dispatch.</p><a href="/project/railway-depot/">Explore the project ↗</a></article><article class="mini-list"><span>04 / TECHNOLOGY</span><h2>Aurora Engine</h2><p>A modular C++ and Unreal framework for NPC perception, memory and decisions.</p><a href="/project/aurora-engine/">Explore the project ↗</a></article></section>''','project/index.html')
page('Talents — Tsushima Mewa','Meet Tsushima Mewa, Aurora Studio’s virtual talent and host of Mewa Ch., exploring Hong Kong urban folklore through 3D environments.','''<section class="talent-hero"><div class="talent-hero-copy"><p class="eyebrow">AURORA STUDIO · VIRTUAL TALENT</p><h1>Tsushima<br><em>Mewa.</em></h1><p class="talent-japanese" lang="ja">津島真羽 · 津島メワ</p><p>From the world of Revenant of Tsushima to the streets and stories of Hong Kong. Meet the virtual host behind Mewa Ch.</p><div class="actions"><a class="button light" href="https://www.youtube.com/@shiko_0215" target="_blank" rel="noopener noreferrer">Watch Mewa Ch. ↗</a><a class="text-link" href="#story">Discover her story ↓</a></div></div><div class="talent-hero-art"><img src="/assets/revenant-cover-clean.jpg" alt="Revenant of Tsushima artwork featuring Tsushima Mewa" width="1200" height="675"><span>ORIGINAL CHARACTER · REVENANT OF TSUSHIMA</span></div></section><section class="section talent-intro" id="story"><div><p class="eyebrow dark">MEET THE TALENT</p><h2>A shrine maiden<br>with another life.</h2></div><div><p>Tsushima Mewa is Aurora Studio’s original character and the protagonist of <a href="/project/revenant-of-tsushima/">Revenant of Tsushima</a>. In the game’s fiction, she is a supernatural shrine maiden awakened after more than three centuries of confinement, with an ability to perceive what others cannot.</p><p>On Mewa Ch., that perspective becomes a way into Hong Kong’s urban folklore: local stories, familiar places and virtual environments that invite viewers to look closer.</p></div></section><section class="talent-feature"><div class="section talent-feature-inner"><p class="eyebrow">MEWA CH. · THE FORMAT</p><h2>Walk into the story.</h2><p>Hong Kong paranormal stories meet 3D scene reconstruction and a virtual host. Episodes use the language of games and spatial storytelling to explore the settings behind urban legends. Where a story is a rumour or a recreation, we present it as such.</p><a class="button light" href="https://www.youtube.com/@shiko_0215" target="_blank" rel="noopener noreferrer">Visit the channel ↗</a></div></section><section class="section talent-links"><div class="section-head"><p class="eyebrow dark">FOLLOW THE WORLDS</p></div><div class="talent-link-grid"><a href="https://www.youtube.com/@shiko_0215" target="_blank" rel="noopener noreferrer"><span>01 / WATCH</span><h3>Mewa Ch.</h3><p>Hong Kong urban folklore, virtual investigations and new videos.</p><b>Open YouTube ↗</b></a><a href="/project/revenant-of-tsushima/"><span>02 / PLAY THE STORY</span><h3>Revenant of Tsushima</h3><p>Explore the folk horror game and the world where Mewa began.</p><b>Explore the project ↗</b></a><a href="/contact/"><span>03 / COLLABORATE</span><h3>Work with Aurora Studio</h3><p>For media, creative collaborations and enquiries about Mewa Ch.</p><b>Get in touch ↗</b></a></div></section>''','talents/index.html')
